<?php
namespace App\Http\Controllers;
use App\Exports\DriverOpeningReceivableExport;
use App\Models\{AccountMapping,Driver,DriverReceivable};
use App\Services\{AuditLogService,PeriodLockService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Maatwebsite\Excel\Facades\Excel;
class DriverOpeningReceivableController extends Controller {
 public function __construct(private PeriodLockService $locks){}
 public function index(Request $r){$query=$this->openingQuery($r)->with('driver');$totals=(clone $query)->selectRaw('COUNT(*) as count, COALESCE(SUM(amount),0) as amount, COALESCE(SUM(paid),0) as paid, COALESCE(SUM(balance),0) as balance')->first();$printMode=$r->boolean('print');$rows=$printMode?(clone $query)->orderBy('date')->orderBy('number')->get():(clone $query)->orderByDesc('date')->paginate(20)->withQueryString();$drivers=Driver::where('is_active',true)->orderBy('code')->get();return view('driver-opening-receivables.index',compact('rows','totals','printMode','drivers'));}
 public function export(Request $r){$rows=$this->openingQuery($r)->with('driver')->orderBy('date')->orderBy('number')->get();return Excel::download(new DriverOpeningReceivableExport($rows,trim((string)$r->input('search')),trim((string)$r->input('driver_id'))),'saldo-awal-piutang-sopir-'.now()->format('Ymd-His').'.xlsx');}
 public function create(){return view('driver-opening-receivables.form',$this->data());}
 public function store(Request $r){$v=$this->valid($r);$coaId=AccountMapping::getCoaId('driver_receivable');if(!$coaId)return back()->withInput()->with('error','Mapping akun Piutang Sopir belum tersedia.');if($this->locks->isLocked($v['date']))return back()->withInput()->with('error',$this->locks->lockedMessage($v['date']));DB::transaction(function()use($v,$coaId){$row=DriverReceivable::create($v+['origin'=>'OPENING','type'=>'SALDO_AWAL','paid'=>0,'balance'=>$v['amount'],'status'=>'OPEN','receivable_coa_id'=>$coaId,'counter_coa_id'=>null,'journal_id'=>null,'created_by'=>auth()->id()]);app(AuditLogService::class)->record('create','driver-opening-receivables',$row,'Membuat saldo awal piutang sopir '.$row->number);});return redirect()->route('driver-opening-receivables.index')->with('success','Saldo awal piutang sopir berhasil disimpan tanpa penjurnalan.');}
 public function edit(DriverReceivable $driver_opening_receivable){$this->guard($driver_opening_receivable);return view('driver-opening-receivables.form',$this->data()+['row'=>$driver_opening_receivable]);}
 public function update(Request $r,DriverReceivable $driver_opening_receivable){$this->guard($driver_opening_receivable);$v=$this->valid($r,$driver_opening_receivable);$v['number']=$driver_opening_receivable->number;if($this->locks->isLocked($v['date']))return back()->withInput()->with('error',$this->locks->lockedMessage($v['date']));DB::transaction(function()use($v,$driver_opening_receivable){$row=DriverReceivable::whereKey($driver_opening_receivable->id)->lockForUpdate()->firstOrFail();$this->guard($row);$v['number']=$row->number;$row->update($v+['balance'=>$v['amount']]);app(AuditLogService::class)->record('update','driver-opening-receivables',$row,'Mengubah saldo awal piutang sopir '.$row->number);});return redirect()->route('driver-opening-receivables.index')->with('success','Saldo awal piutang sopir berhasil diperbarui tanpa penjurnalan.');}
 public function destroy(DriverReceivable $driver_opening_receivable){$this->guard($driver_opening_receivable);DB::transaction(function()use($driver_opening_receivable){$row=DriverReceivable::whereKey($driver_opening_receivable->id)->lockForUpdate()->firstOrFail();$this->guard($row);app(AuditLogService::class)->record('delete','driver-opening-receivables',$row,'Menghapus saldo awal piutang sopir '.$row->number);$row->delete();});return back()->with('success','Saldo awal piutang sopir berhasil dihapus tanpa penjurnalan.');}
 private function valid(Request $r,?DriverReceivable $row=null):array{return $r->validate(['number'=>['required','string','max:40',Rule::unique('driver_receivables')->ignore($row?->id)],'date'=>['required','date'],'due_date'=>['nullable','date','after_or_equal:date'],'driver_id'=>['required','exists:drivers,id'],'vehicle_number'=>['nullable','string','max:30'],'reference'=>['nullable','string','max:100'],'amount'=>['required','numeric','gt:0'],'description'=>['required','string','max:1000']]);}
 private function data():array{return ['drivers'=>Driver::where('is_active',true)->orderBy('code')->get()];}
 private function openingQuery(Request $r){return DriverReceivable::query()->where('origin','OPENING')->when($r->filled('driver_id'),fn($q)=>$q->where('driver_id',(int)$r->input('driver_id')))->when($r->filled('search'),function($q)use($r){$s=trim((string)$r->input('search'));$q->where(fn($x)=>$x->where('number','like',"%{$s}%")->orWhere('reference','like',"%{$s}%")->orWhere('vehicle_number','like',"%{$s}%")->orWhereHas('driver',fn($d)=>$d->where('code','like',"%{$s}%")->orWhere('name','like',"%{$s}%")));});}
 private function guard(DriverReceivable $r):void{abort_unless($r->origin==='OPENING',404);abort_if((float)$r->paid>0||$r->payments()->where('status','POSTED')->exists(),422,'Saldo awal yang sudah dibayar tidak dapat diubah atau dihapus.');abort_if($this->locks->isLocked($r->date),422,$this->locks->lockedMessage($r->date));}
}
